import type { ComboboxClearIconButtonProps } from "../combobox.types";

import React from "react";
import { clsx } from "clsx";
import { Clear as DefaultClearIcon } from "@exp-textura/icons";
import { IconButton } from "@components/icon-button";

import { useComboboxState } from "../hooks/use-combobox-state";
import { useComboboxInteraction } from "../hooks/use-combobox-interaction";
import { ComboboxClasses } from "../combobox.styles";

const ComboboxClearIconButton: React.FC<ComboboxClearIconButtonProps> = ({
  children,
  className,
  "aria-label": customAriaLabel,
  hideWhenEmpty = true,
}) => {
  const { value, disabled, inputValue, inputRef } = useComboboxState();
  const { clearValue } = useComboboxInteraction();
  const buttonClasses = clsx(ComboboxClasses.clearIconButton, className);

  const commonProps = {
    "aria-label": customAriaLabel || "clear selected value",
  };

  if (!value && !inputValue && hideWhenEmpty) {
    return null;
  }

  const handleClear = () => {
    clearValue();
    queueMicrotask(() => {
      inputRef.current?.focus();
    });
  };

  return (
    <IconButton
      buttonType="secondary"
      className={buttonClasses}
      disabled={disabled}
      size="sm"
      onClick={(e) => {
        e.stopPropagation();
        e.preventDefault();
        handleClear();
      }}
      onKeyDown={(e) => e.stopPropagation()}
      onPointerDown={(e) => e.preventDefault()}
      {...commonProps}
    >
      {children || <DefaultClearIcon />}
    </IconButton>
  );
};

ComboboxClearIconButton.displayName = "Combobox.ClearIconButton";

export { ComboboxClearIconButton };
